{
  "description": "The creature is shown in right-facing side profile standing on a pale ground against a plain light background. It is a stout, low-slung quadruped with an elongated body, a broad flattened head at the front, four short thick legs beneath the body, and a long thick tapering tail that extends from the rear and arches up and forward over the back. The dorsal, lateral, and top-of-head surfaces are covered in overlapping large brown scales, while the ventral surface, throat, inner leg joints, tail underside, and snout are pale pink wrinkled skin. The head has large prominent blue eyes with black pupils, small nostrils at the tip of the snout, a wide slightly upturned mouth, and multiple pink feathery external gill stalks protruding from the neck just behind the head on both sides. The feet are pink with five slender claw-tipped toes.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and rounded at the snout, axolotl-like, with large round blue eyes with black pupils and light rims, small circular nostrils at the tip, a wide mouth with pale pink jowls, dark speckling on the cheeks and snout, top of head covered in small overlapping brown scales, sides and throat in pale pink wrinkled skin",
      "where": "at the front end of the body, facing to the right"
    },
    {
      "part": "gills",
      "looks_like": "pink fleshy stalks with fine feathery filaments along their length, four stalks visible on the near side of the neck pointing outward and forward, three stalks visible on the far side protruding above the head, all with dense pink fimbriae",
      "where": "emerging from the sides of the neck immediately behind the head, on both left and right sides"
    },
    {
      "part": "legs",
      "looks_like": "short, stout, columnar, outer surfaces covered in overlapping brown diamond-shaped scales, inner surfaces and joints showing pale pink wrinkled skin with visible folds",
      "where": "four legs positioned under the body, two forelegs under the chest and two hindlegs under the mid-body/rear"
    },
    {
      "part": "feet",
      "looks_like": "pale pink with wrinkled skin, each with five slender toes tipped with small light tan claws, toes splayed on the ground",
      "where": "at the distal ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering toward the tip, fleshy with mottled gray-brown skin bearing darker spots, base partially overlapped by the body scales, the visible length curves upward and forward over the back",
      "where": "extending from the rear of the body, arching dorsally over the scaled back"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, keeled, diamond to teardrop-shaped keratinous scales in shades of brown with darker edges and lighter centers, arranged in regular rows covering the back, sides, top of head, and outer legs",
      "where": "covering the dorsal and lateral surfaces of the body from the head to the tail base, and the outer surfaces of the legs"
    },
    {
      "part": "markings",
      "looks_like": "small dark brown to black speckles clustered on the snout and around the eyes, and irregular darker mottling and spotting on the fleshy tail and on the pale ventral skin",
      "where": "on the face around the nostrils and eyes, and on the exposed pink skin of the tail and underbelly"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
